<script setup lang="ts">
import type { BsCommodityCopy, BsCommodityForm, BsCommodityKind, BsCommodityPicker, BsCommodityRow, BsCommodityView } from '../types/commodityPricingPresentation'
const props=defineProps<{copy:BsCommodityCopy;view:BsCommodityView;rows:BsCommodityRow[];products:BsCommodityPicker;quotes:BsCommodityPicker}>()
const mode=defineModel<BsCommodityKind>('mode',{required:true}),search=defineModel<string>('search',{required:true}),page=defineModel<number>('page',{required:true}),historyPage=defineModel<number>('historyPage',{required:true}),editorOpen=defineModel<boolean>('editorOpen',{required:true}),historyOpen=defineModel<boolean>('historyOpen',{required:true}),form=defineModel<BsCommodityForm>('form',{required:true})
const emit=defineEmits<{retry:[];retryHistory:[];add:[];edit:[id:string];history:[id:string];submit:[];product:[id:string];quote:[id:string];productSearch:[query:string];productMore:[];productRetry:[];quoteSearch:[query:string];quoteMore:[];quoteRetry:[]}>()
function change<K extends keyof BsCommodityForm>(key:K,value:BsCommodityForm[K]){form.value={...form.value,[key]:value}}
const columns=computed(()=>[{key:'name',field:'name',header:props.copy.name},{key:'source',field:'source',header:props.copy.source},{key:'value',field:'value',header:props.copy.price},{key:'validity',field:'validity',header:props.copy.validity},{key:'status',field:'status',header:props.copy.active},{key:'revision',field:'revision',header:props.copy.revision},{key:'actions',header:props.copy.history}])
const historyColumns=computed(()=>[{key:'revision',field:'revision',header:props.copy.revision},{key:'reason',field:'reason',header:props.copy.reason},{key:'changes',field:'changes',header:props.copy.changes},{key:'actor',field:'actor',header:props.copy.actor},{key:'date',field:'date',header:props.copy.date}])
</script>
<template>
 <BsStack gap="lg">
  <BsPageHeader :title="copy.title" :subtitle="copy.subtitle"><template #actions><BsLink to="/pos">{{ copy.pos }}</BsLink><BsButton v-if="view.canManage" :disabled="view.locked || editorOpen || historyOpen" @click="emit('add')">{{ copy.add }}</BsButton></template></BsPageHeader>
  <BsText as="p" tone="muted">{{ copy.policy }}</BsText>
  <BsText v-if="!view.available">{{ copy.noShop }}</BsText>
  <BsStack v-else gap="md"><BsSelect :model-value="mode" :label="copy.mode" :options="view.modes" option-label="label" option-value="value" :disabled="view.locked || editorOpen || historyOpen" @update:model-value="mode=String($event) as BsCommodityKind" />
   <BsDataTable v-model:search="search" :value="rows" :columns="columns" data-key="id" :label="mode === 'quote' ? copy.quotes : copy.rules" searchable lazy paginator :rows="20" :first="(page-1)*20" :total-records="view.total" :loading="view.loading" :error="view.error" @page="page=$event.page+1" @retry="emit('retry')"><template #cell-actions="{row}"><BsInline wrap><BsButton :disabled="!view.canManage || view.locked || editorOpen || historyOpen" variant="secondary" @click="emit('edit',row.id)">{{ copy.edit }}</BsButton><BsButton :disabled="view.locked || editorOpen || historyOpen" variant="text" @click="emit('history',row.id)">{{ copy.history }}</BsButton></BsInline></template><template #empty><BsText>{{ copy.empty }}</BsText></template></BsDataTable>
  </BsStack>
  <BsRecordActionDialog v-model:visible="editorOpen" :title="view.editor.title" :dirty="view.editor.dirty" :pending="view.editor.pending" :close-blocked="view.locked" :error="view.editor.error" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="view.editor.unitLoading" pinned-actions size="lg" @submit="emit('submit')">
   <BsText as="p" tone="muted">{{ view.editor.notice }}</BsText>
   <BsText as="p">{{ copy.currency }}: {{ view.currency }}</BsText>
   <template v-if="mode === 'quote'">
    <BsField v-slot="f" for="commodity-name" :label="copy.commodity"><BsInput :id="f.id" :model-value="form.commodity" required :minlength="2" :maxlength="120" :disabled="view.locked || view.editor.quoteIdentityLocked" @update:model-value="change('commodity',String($event))" /></BsField>
    <BsField v-slot="f" for="commodity-source" :label="copy.sourceName"><BsInput :id="f.id" :model-value="form.sourceName" required :minlength="3" :maxlength="120" :disabled="view.locked || view.editor.quoteIdentityLocked" @update:model-value="change('sourceName',String($event))" /></BsField>
    <BsField v-slot="f" for="commodity-price" :label="copy.pricePerKg"><BsInput :id="f.id" :model-value="form.pricePerKg" inputmode="decimal" required :disabled="view.locked || view.editor.quoteIdentityLocked" @update:model-value="change('pricePerKg',String($event))" /></BsField>
    <BsGrid :columns="2"><BsField v-slot="f" for="commodity-start" :label="copy.effectiveAt"><BsInput :id="f.id" :model-value="form.effectiveAt" type="datetime-local" required :disabled="view.locked || view.editor.quoteIdentityLocked" @update:model-value="change('effectiveAt',String($event))" /></BsField><BsField v-slot="f" for="commodity-end" :label="copy.expiresAt"><BsInput :id="f.id" :model-value="form.expiresAt" type="datetime-local" required :disabled="view.locked || view.editor.quoteIdentityLocked" @update:model-value="change('expiresAt',String($event))" /></BsField></BsGrid>
   </template>
   <template v-else>
    <BsEntityPicker :model-value="form.productId" :label="copy.product" :options="products.options" option-label="name" option-value="id" :loading="products.loading" :error="products.error" :has-more="products.hasMore" :load-more-label="copy.more" :retry-label="copy.retry" :disabled="view.locked || view.editor.productLocked" @update:model-value="emit('product',String($event??''))" @search="emit('productSearch',$event)" @load-more="emit('productMore')" @retry="emit('productRetry')" />
    <BsText as="p">{{ copy.unit }}: {{ view.editor.unit || '—' }}</BsText>
    <BsEntityPicker :model-value="form.quoteId" :label="copy.quote" :options="quotes.options" option-label="name" option-value="id" :loading="quotes.loading" :error="quotes.error" :has-more="quotes.hasMore" :load-more-label="copy.more" :retry-label="copy.retry" :disabled="view.locked" @update:model-value="emit('quote',String($event??''))" @search="emit('quoteSearch',$event)" @load-more="emit('quoteMore')" @retry="emit('quoteRetry')" />
    <BsField v-slot="f" for="commodity-content" :label="copy.kgPerBaseUnit"><BsInput :id="f.id" :model-value="form.kgPerBaseUnit" inputmode="decimal" required :disabled="view.locked || view.editor.unitLoading" @update:model-value="change('kgPerBaseUnit',String($event))" /></BsField>
    <BsField v-slot="f" for="commodity-premium" :label="copy.premium"><BsInput :id="f.id" :model-value="form.premiumPerBaseUnit" inputmode="decimal" required :disabled="view.locked" @update:model-value="change('premiumPerBaseUnit',String($event))" /></BsField>
   </template>
   <BsField v-slot="f" for="commodity-evidence" :label="copy.evidence"><BsTextarea :id="f.id" :model-value="form.evidenceReference" required :minlength="3" :maxlength="500" :disabled="view.locked || view.editor.quoteIdentityLocked" @update:model-value="change('evidenceReference',String($event))" /></BsField>
   <BsCheckbox :model-value="form.active" :label="copy.active" :disabled="view.locked" @update:model-value="change('active',Boolean($event))" /><BsCheckbox :model-value="form.confirmed" :label="copy.confirm" :disabled="view.locked" @update:model-value="change('confirmed',Boolean($event))" />
   <BsField v-slot="f" for="commodity-reason" :label="copy.reason"><BsTextarea :id="f.id" :model-value="form.reason" required :minlength="3" :maxlength="500" :disabled="view.locked" @update:model-value="change('reason',String($event))" /></BsField>
  </BsRecordActionDialog>
  <BsDialog v-model:visible="historyOpen" :title="view.history.title" size="lg"><BsText v-if="view.history.loading" role="status">{{ copy.retry }}</BsText><BsStack v-else-if="view.history.error"><BsText role="alert">{{ view.history.error }}</BsText><BsButton @click="emit('retryHistory')">{{ copy.retry }}</BsButton></BsStack><BsStack v-else gap="md"><BsDescriptionList><BsDescriptionItem v-for="field in view.history.fields" :key="field.label" :term="field.label">{{ field.value }}</BsDescriptionItem></BsDescriptionList><BsDataTable :value="view.history.events" :columns="historyColumns" data-key="id" :label="copy.history" lazy paginator :rows="20" :first="(historyPage-1)*20" :total-records="view.history.total" @page="historyPage=$event.page+1" /></BsStack><template #footer="{ close }"><BsButton @click="close">{{ copy.close }}</BsButton></template></BsDialog>
 </BsStack>
</template>
